public static class Eintritt
{
    public static decimal Preis(int alter)
    {
        if (alter < 0)
            throw new
              ArgumentOutOfRangeException(
                nameof(alter));
        if (alter <= 5) return 0m;
        if (alter <= 17) return 4m;
        return 8m;
    }
}

using Xunit;

public class EintrittTests
{
    [Fact]
    public void Preis_Alter5_IstGratis()
    {
        // Arrange
        int alter = 5;
        // Act
        decimal p = Eintritt.Preis(alter);
        // Assert
        Assert.Equal(0m, p);
    }
}

[Theory]
[InlineData(0, 0)]
[InlineData(5, 0)]
[InlineData(6, 4)]
[InlineData(17, 4)]
[InlineData(18, 8)]
public void Preis_Grenzwerte(
    int alter, int erwartet)
{
    Assert.Equal((decimal)erwartet,
        Eintritt.Preis(alter));
}

[Fact]
public void Preis_Negativ_Wirft()
{
    Assert.Throws<
        ArgumentOutOfRangeException>(
        () => Eintritt.Preis(-1));
}

[Fact]
public void Schnitt_1_2_2()
{
    double s = new[] { 1, 2, 2 }
        .Average();
    Assert.Equal(1.67, s, 2);
}

